#!/usr/bin/env dotnet
// friday13.cs — Find earliest Friday the 13th and count them in a 400-year cycle

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
while (date.DayOfWeek != DayOfWeek.Friday)
{
    date = date.AddMonths(1);
}
Console.WriteLine($"Earliest Friday the 13th (proleptic Gregorian): {date:yyyy-MM-dd}");

// Count Friday the 13ths in a full 400-year cycle (0001-01-13 to 0400-12-13)
int count = 0;
var current = new DateTime(1, 1, 13);
var end = new DateTime(400, 12, 31);
while (current <= end)
{
    if (current.DayOfWeek == DayOfWeek.Friday)
        count++;
    current = current.AddMonths(1);
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: distribution by day of week for the 13th
var dayCounts = new int[7];
current = new DateTime(1, 1, 13);
while (current <= end)
{
    dayCounts[(int)current.DayOfWeek]++;
    current = current.AddMonths(1);
}
Console.WriteLine("\nDistribution of the 13th by day of week (400-year cycle):");
foreach (DayOfWeek day in Enum.GetValues<DayOfWeek>())
{
    Console.WriteLine($"  {day,-9}: {dayCounts[(int)day]}");
}

